SELECT id AS value,jsonb_build_object('id',id::text,'discordId',discord_id::text,'kind',kind, 'targetId',target_id,'paused',paused,'lastError',last_error,'lastDeliveryKey',last_delivery_key, 'dateCreated',to_char(date_created AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS payload FROM zc_private.discord_watch WHERE paused=false AND kind=$1 AND target_id=ANY($2)
